Generate TypeScript interfaces from JSON safely. Here's how to do it right.
// Interface — preferred for JSON object shapes
interface User {
    id: number;
    name: string;
    email: string;
    active: boolean;
}

// Type alias — better for unions and computed types
type UserId = number;
type Status = 'active' | 'inactive' | 'pending';
type UserOrAdmin = User | AdminUser;

interface User {
    id: number;
    name: string;
    email: string;
    bio?: string;           // optional — may be absent
    avatarUrl?: string;     // optional — may be absent
}

// Index signatures for dynamic keys
interface Metadata {
    [key: string]: string | number | boolean;
}

// JSON value type
type JsonValue =
    | string
    | number
    | boolean
    | null
    | JsonValue[]
    | { [key: string]: …

Convert JSON to Rust structs using serde_json. Here's everything Rust developers need.
[dependencies]
serde = { version = "1", features = ["derive"] }
serde_json = "1"

use serde::{Serialize, Deserialize};

#[derive(Debug, Serialize, Deserialize)]
struct User {
    id: u32,
    name: String,
    email: String,
    active: bool,
}

// Deserialize
let user: User = serde_json::from_str(json_str)?;

// Serialize
let json = serde_json::to_string(&user)?;
let pretty = serde_json::to_string_pretty(&user)?;

use serde::{Serialize, Deserialize};

// camelCase JSON → snake_case Rust
#[derive(Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ApiResponse {
    user_id: u32,        // maps to "userId"
    first_name: String,  // maps to "firstName"
    avatar_url: String,  // maps to "…

Converting JSON to Kotlin data classes for Android and multiplatform apps. Here's everything you need.
import kotlinx.serialization.Serializable
import kotlinx.serialization.SerialName

@Serializable
data class User(
    val id: Int,
    val name: String,
    val email: String,
    val active: Boolean,
    @SerialName("avatar_url")
    val avatarUrl: String? = null
)

// Deserialize
val user = Json.decodeFromString<User>(jsonString)

// Serialize
val json = Json.encodeToString(user)

// build.gradle: implementation 'com.google.code.gson:gson:2.11.0'
data class User(
    val id: Int,
    val name: String,
    @SerializedName("avatar_url")
    val avatarUrl: String?
)

val gson = Gson()
val user = gson.fromJson(jsonString, User::class.java)
val serialized = gson.toJson(user)

// build.gradle…
